Aquí hay una función que verifica si un número es primo y luego verifica si algún número en un array de 5 es primo y lo imprime en la consola:

```javascript
function esPrimo(n) {
  if (n < 2) {
    return false;
  }
  for (let I = 2; I <= Math.sqrt(n); i++) {
    if (n % I === 0) {
      return false;
    }
  }
  return true;
}

function esArrayDeCincoNumeros(array) {
  return array.length === 5 && array.every(Number.isInteger);
}

function encontrarPrimo(array) {
  if (!esArrayDeCincoNumeros(array)) {
    throw new Error('Debe proporcionar un array de 5 números enteros');
  }

  for (let I = 0; I < array.length; i++) {
    if (esPrimo(array[i])) {
      console.log(`El número ${array[i]} es primo`);
    }
  }
}

// Ejemplo de uso:
const array = [2, 7, 12, 19, 31];
encontrarPrimo(array);
```

La función `esPrimo()` verifica si un número es primo, y la función `esArrayDeCincoNumeros()` verifica que el array tenga 5 elementos y que todos sean números enteros. La función `encontrarPrimo()` llama a las otras dos funciones y verifica si algún número en el array es primo, imprimiendo el número en la consola si es así. Si el array no cumple con los requisitos, se lanza un error.

